<script setup>
import { ref,watch,onMounted,onUnmounted } from 'vue';
import { Search,Download,RefreshCw,ChevronDown } from 'lucide-vue-next';
const props=defineProps({api:Function,notify:Function,clients:Array,timezone:String});
const level=ref(''),scope=ref(''),query=ref(''),client=ref(''),period=ref('24h'),page=ref(1),result=ref({rows:[],total:0,page:1,pageSize:50}),error=ref(''),loading=ref(false),expanded=ref(new Set());let timer,debounce,seq=0;
const levels={info:'信息',success:'成功',warning:'警告',error:'错误'},scopes={connection:'连接',control:'限速调度',config:'配置',http:'接口',system:'系统'};
function params(){const p=new URLSearchParams({level:level.value,scope:scope.value,q:query.value,client:client.value,page:String(page.value)});if(period.value!=='all')p.set('from',String(Date.now()-({'1h':3600000,'24h':86400000,'7d':604800000}[period.value])));return p.toString();}
async function load(){const id=++seq;loading.value=true;try{const value=await props.api('logs?'+params());if(id===seq){result.value=value;error.value='';}}catch(e){if(id===seq)error.value=e.message;}finally{if(id===seq)loading.value=false;}}
watch([level,scope,client,period],()=>{page.value=1;load();});watch(query,()=>{clearTimeout(debounce);debounce=setTimeout(()=>{page.value=1;load();},300);});watch(page,load);
onMounted(()=>{load();timer=setInterval(load,15000);});onUnmounted(()=>{seq++;clearTimeout(debounce);clearInterval(timer);});
const date=value=>new Intl.DateTimeFormat('zh-CN',{timeZone:props.timezone||'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(value);
function toggle(id){const set=new Set(expanded.value);set.has(id)?set.delete(id):set.add(id);expanded.value=set;}
async function download(){try{const bundle=await props.api('diagnostics?'+params());const url=URL.createObjectURL(new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='torrent-harbor-diagnostics-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url);props.notify('诊断文件已导出，包含筛选条件内最近 200 条日志');}catch(e){props.notify(e.message,true);}}
</script>
<template><section class="panel logs-panel"><div class="panel-head"><div><h2>诊断日志</h2><p>按问题定位连接、调度和请求；展开可查看完整上下文。</p></div><div class="logs-actions"><button class="btn" @click="load" :disabled="loading"><RefreshCw :size="14"/>刷新日志</button><button class="btn" @click="download"><Download :size="14"/>导出诊断</button></div></div><div class="log-filters"><div class="search-field"><Search :size="16"/><input v-model="query" aria-label="搜索日志" placeholder="搜索错误、操作或任务标识"></div><select v-model="level" aria-label="日志级别"><option value="">全部级别</option><option v-for="(label,id) in levels" :key="id" :value="id">{{label}}</option></select><select v-model="scope" aria-label="日志模块"><option value="">全部模块</option><option v-for="(label,id) in scopes" :key="id" :value="id">{{label}}</option></select><select v-model="client" aria-label="日志下载器"><option value="">所有下载器</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select><select v-model="period" aria-label="日志时间范围"><option value="1h">最近 1 小时</option><option value="24h">最近 24 小时</option><option value="7d">最近 7 天</option><option value="all">全部时间</option></select></div><p v-if="error" role="alert" class="error-message">{{error}}</p><div class="table-scroll"><table class="log-table"><thead><tr><th>时间 / 级别</th><th>模块 / 下载器</th><th>记录内容</th><th>次数</th><th>详情</th></tr></thead><tbody><template v-for="row in result.rows" :key="row.id"><tr><td><time>{{date(row.time)}}</time><span class="log-level" :class="row.level">{{levels[row.level]}}</span></td><td>{{scopes[row.scope]||row.scope}}<small>{{row.context.clientName||clients.find(c=>c.id===row.context.clientId)?.name||'—'}}</small></td><td class="log-message"><strong>{{row.message}}</strong><span>{{row.context.detail||row.context.error||row.code}}</span></td><td><span :title="'首次出现 '+date(row.first_time)">{{row.repeats}}</span></td><td><button class="icon-button" :aria-label="'查看日志 '+row.id+' 详情'" :aria-expanded="expanded.has(row.id)" @click="toggle(row.id)"><ChevronDown :size="16"/></button></td></tr><tr v-if="expanded.has(row.id)" class="log-detail"><td colspan="5"><p>编号 {{row.id}} · {{row.code}} · 首次 {{date(row.first_time)}} · 最近 {{date(row.time)}}</p><pre>{{JSON.stringify(row.context,null,2)}}</pre></td></tr></template><tr v-if="!result.rows.length&&!error"><td colspan="5" class="empty-table">{{loading?'正在读取日志…':'当前筛选下没有日志'}}</td></tr></tbody></table></div><div class="pagination"><span>共 {{result.total}} 条 · 每页 50 条</span><div><button class="btn small" :disabled="result.page<=1" @click="page=result.page-1">上一页</button><span>{{result.page}} / {{Math.max(1,Math.ceil(result.total/50))}}</span><button class="btn small" :disabled="result.page*50>=result.total" @click="page=result.page+1">下一页</button></div></div></section><p class="page-note">日志最多保留 30 天、10,000 条；相同问题在 60 秒内合并计数。导出包含版本和连接状态，凭证自动隐藏。</p></template>
